1	export type Item = {
2	  type: string;
3	};
4	
5	export type Scenario = {
6	  customer: { yearsWithMHPCO: number };
7	  steps: { op: string; items: Item[] }[];
8	};
9	
10	export type ScenarioResult = {
11	  results: { premium: number }[];
12	};
13	
14	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
15	  sword: 100,
16	  amulet: 60,
17	  staff: 80,
18	  potion: 40,
19	  rune: 25,
20	  moonstone: 25,
21	};
22	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
23	const PROCESSING_FEE = 5;
24	
25	const percentOf = (amount: number, percent: number): number =>
26	  (amount * percent) / 100;
27	
28	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
29	
30	const BLOCK_SIZE = 3;
31	const BLOCK_BASE_PREMIUM = 60;
32	
33	const distinctTypes = (items: Item[]): string[] => [
34	  ...new Set(items.map((item) => item.type)),
35	];
36	
37	const countOfType = (items: Item[], type: string): number =>
38	  items.filter((item) => item.type === type).length;
39	
40	const formsBuildingBlock = (count: number): boolean => count === BLOCK_SIZE;
41	
42	const basePremiumForGroup = (type: string, count: number): number =>
43	  formsBuildingBlock(count)
44	    ? BLOCK_BASE_PREMIUM
45	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
46	
47	const policyBasePremium = (items: Item[]): number =>
48	  distinctTypes(items)
49	    .map((type) => basePremiumForGroup(type, countOfType(items, type)))
50	    .reduce((total, groupPremium) => total + groupPremium, 0);
51	
52	const quotePremium = (items: Item[]): number => {
53	  const basePremium = policyBasePremium(items);
54	  const withFirstInsuranceSurcharge =
55	    basePremium + percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
56	  return roundInMHPCOsFavour(withFirstInsuranceSurcharge + PROCESSING_FEE);
57	};
58	
59	export const runScenario = (scenario: Scenario): ScenarioResult => ({
60	  results: scenario.steps.map((step) => ({
61	    premium: quotePremium(step.items),
62	  })),
63	});
